import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_none_counts_as_unconverted():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5
    assert conversion_rate([]) == 0.0


def test_duplicate_id_keeps_last_input_record_then_sorts():
    old, other, new, first = parse_session_log(["a,9,0", "b,3,0", "a,3,1", "z,1,0"])
    assert dedupe_sessions([old, other, new, first]) == [first, new, other]


def test_parse_skips_comments_and_blanks_and_strips_fields():
    assert parse_session_log(["", "  # comment", " \t", " a , 1 , 0 ", " b , 2 , "]) == [
        {"id": "a", "day": 1, "converted": False},
        {"id": "b", "day": 2, "converted": None},
    ]


@pytest.mark.parametrize("bad", ["a,1", "a,1,1,0", "a,no,0"])
def test_parse_error_reports_original_line(bad):
    with pytest.raises(ValueError, match=r"line 3\b"):
        parse_session_log(["# header", " ", bad])


def test_daily_counts_and_window_boundaries():
    events = parse_session_log(["x,0,1", "a,1,1", "b,1,1", "c,2,0", "d,5,1"])
    counts = daily_conversion_counts(events, 1, 4)
    assert counts == [2, 0, 0, 0]
    assert daily_conversion_counts(events, 4, 1) == []
    assert conversions_in_window(counts, 0) == 0
    assert conversions_in_window(counts, 3) == 0
    assert conversions_in_window(counts, 5) == 2


def test_campaign_summary_weights_sessions_and_includes_gaps():
    groups = {"a": parse_session_log(["x,1,1"]), "b": parse_session_log(["y,3,0", "z,4,0"]), "c": []}
    assert campaign_summary(groups, 3) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert campaign_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert pooled_conversion_rate({}) == 0.0


def test_group_ordering_ties_and_empty_groups():
    groups = {"z": [{"converted": True}], "a": [{"converted": False}], "x": [], "b": [{"converted": True}]}
    assert list(conversion_rate_by_group(groups).items()) == [("a", 0.0), ("b", 1.0), ("x", None), ("z", 1.0)]
    assert top_converting_groups(groups, 1) == ["b"]
    assert top_converting_groups(groups, 5) == ["b", "z", "a"]


def test_streak_counts_consecutive_positive_days_only():
    assert longest_conversion_streak([1, 0, 1, 2, -1, 3]) == 2
    assert longest_conversion_streak([]) == 0
    assert longest_conversion_streak([-1, 0]) == 0
